	if _, err := e.UpdateQuote("A", Quote{Seq: 0, Moment: 1, Price: 10}); err == nil {
		t.Fatal("序号 0 必须报错")
	}
	if _, err := e.UpdateQuote("A", Quote{Seq: 1, Moment: 1, Price: 0}); err == nil {
		t.Fatal("非正价格必须报错")
	}
	if _, err := e.UpdateQuote("", Quote{Seq: 1, Moment: 1, Price: 10}); err == nil {

